alter table public.recording_sessions add column if not exists drive_folder_id text; alter table public.recording_fragments add column if not exists drive_file_id text,add column if not exists drive_uploaded_at timestamptz,add column if not exists drive_error text; create unique index if not exists recording_sessions_active_device_unique on public.recording_sessions(pelada_id,device_id) where status='RECORDING'; create or replace function public.superadmin_iniciar_gravacao(p_pelada_id uuid,p_device_id text,p_started_at timestamptz,p_server_time_offset_ms integer default 0) returns public.recording_sessions language plpgsql security definer set search_path='' as $$ declare v_session public.recording_sessions; begin if not public.is_superadmin() then raise exception 'Acesso negado'; end if; insert into public.pelada_controles(pelada_id,status,team_queue) values(p_pelada_id,'CREATED','{}') on conflict(pelada_id) do nothing; select * into v_session from public.recording_sessions where pelada_id=p_pelada_id and device_id=p_device_id and status='RECORDING' order by started_at desc limit 1 for update; if found then return v_session; end if; insert into public.recording_sessions(pelada_id,admin_id,device_id,started_at,server_time_offset_ms,status,upload_status) values(p_pelada_id,auth.uid(),p_device_id,p_started_at,p_server_time_offset_ms,'RECORDING','LOCAL') returning * into v_session; insert into public.pelada_dispositivos(pelada_id,user_id,device_id,mode,status,server_time_offset_ms) values(p_pelada_id,auth.uid(),p_device_id,'CAMERA','ONLINE',p_server_time_offset_ms) on conflict(pelada_id,device_id) do update set user_id=excluded.user_id,mode='CAMERA',status='ONLINE',server_time_offset_ms=excluded.server_time_offset_ms,last_seen_at=now(); update public.pelada_controles set recording_session_id=v_session.id,recording_started_at=p_started_at,device_camera_online=true,updated_at=now() where pelada_id=p_pelada_id; return v_session; end $$; create or replace function public.superadmin_finalizar_gravacao(p_session_id uuid,p_ended_at timestamptz) returns public.recording_sessions language plpgsql security definer set search_path='' as $$ declare v_session public.recording_sessions;v_active public.recording_sessions; begin select * into v_session from public.recording_sessions where id=p_session_id for update; if not public.is_superadmin() or v_session.admin_id<>auth.uid() then raise exception 'Acesso negado'; end if; if v_session.status='RECORDING' then update public.recording_sessions set ended_at=p_ended_at,duration_ms=greatest(0,extract(epoch from(p_ended_at-started_at))*1000)::bigint,status='FINISHED',upload_status=case when exists(select 1 from public.recording_fragments where session_id=p_session_id) then 'PENDING' else 'LOCAL' end,updated_at=now() where id=p_session_id returning * into v_session; end if; update public.pelada_dispositivos set status='OFFLINE',last_seen_at=now() where pelada_id=v_session.pelada_id and device_id=v_session.device_id; select * into v_active from public.recording_sessions where pelada_id=v_session.pelada_id and status='RECORDING' order by started_at desc limit 1; update public.pelada_controles set recording_session_id=v_active.id,recording_started_at=v_active.started_at,device_camera_online=(v_active.id is not null),updated_at=now() where pelada_id=v_session.pelada_id; return v_session; end $$;
